sys_ux_data_broker_transform.script:
function transform(input) {
  var result = {};

  // Step 1: Get values from the 'sam.implementation.automation' system property
  var propGr = new GlideRecord('sys_properties');
  propGr.addQuery('name', 'sam.implementation.automation');
  propGr.query();

  var updateSetValues = [];
  if (propGr.next()) {
    try {
      var propValue = JSON.parse(propGr.getValue('value'));
      for (var i = 0; i < propValue.length; i++) {
        if (propValue[i].update_set) {
          updateSetValues.push(propValue[i].update_set);
        }
      }
    } catch (e) {
      gs.log('Error parsing property value: ' + e);
    }
  }

  // Step 2: Query the sys_remote_update_set table with these values
  for (var j = 0; j < updateSetValues.length; j++) {
    var updateSetValue = updateSetValues[j];
    var updateSetGr = new GlideRecord('sys_remote_update_set');
    updateSetGr.addQuery('name', updateSetValue); // Changed from 'update_set' to 'name'
    updateSetGr.query();

    if (updateSetGr.next()) {
      result[updateSetValue] = updateSetGr.getValue('state');
    }
  }

  // Log the result
  //gs.log('data result returned' + JSON.stringify(result, null, 2));

  // Return the result object
  return result;
}
